CREATE TABLE IF NOT EXISTS client_units (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, name TEXT NOT NULL, address TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS client_units_by_client ON client_units (client_id);
CREATE TABLE IF NOT EXISTS client_equipment (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, name TEXT NOT NULL, model TEXT NOT NULL DEFAULT '', serial_number TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS client_equipment_by_client ON client_equipment (client_id);
ALTER TABLE tickets ADD COLUMN unit_id TEXT REFERENCES client_units(id);
ALTER TABLE tickets ADD COLUMN equipment_id TEXT REFERENCES client_equipment(id);
